<script setup lang="ts">
import { computed, inject, onMounted, reactive, ref, watch } from "vue";
import { PhArrowClockwise as ArrowClockwise, PhArrowLeft as ArrowLeft, PhCaretRight as CaretRight, PhCopy as Copy, PhDownloadSimple as DownloadSimple, PhFile as File, PhFileCode as FileCode, PhFolder as Folder, PhFolderOpen as FolderOpen, PhMagnifyingGlass as MagnifyingGlass, PhPencilSimple as PencilSimple, PhPlus as Plus, PhTrash as Trash, PhUploadSimple as UploadSimple, PhX as X } from "@phosphor-icons/vue";
import type { APIClient } from "../api";
import { sessionStore } from "../store";

interface SiteOption { id:string; label:string }
interface FileEntry { path:string; kind:"regular"|"directory"|"symlink"; size:number; mode:number; owner:string; group:string; modified_at:string; etag:string; link_target?:string }
type CreateKind = "file"|"directory";
interface TrashedEntry { id:string; site_id:string; original:{root:{site_id:string;kind:string};path:string} }
const trashed=ref<TrashedEntry[]>([]);
const renameEntry=ref<FileEntry|null>(null);
const renameName=ref("");

const api=inject<APIClient>("api")!;
const sites=ref<SiteOption[]>([]);const siteID=ref("");const rootKind=ref("public");const currentPath=ref("");const entries=ref<FileEntry[]>([]);const nextCursor=ref("");const cursors=ref<string[]>([]);const loading=ref(true);const error=ref("");const search=ref("");const selected=ref<FileEntry|null>(null);const editorOpen=ref(false);const editorLoading=ref(false);const editorContent=ref("");const editorOriginalETag=ref("");const createOpen=ref(false);const create=reactive<{kind:CreateKind;name:string;content:string}>({kind:"file",name:"",content:""});const busy=ref(false);const uploadInput=ref<HTMLInputElement|null>(null);

const visibleEntries=computed(()=>{const term=search.value.trim().toLowerCase();const filtered=term?entries.value.filter((entry)=>basename(entry.path).toLowerCase().includes(term)):entries.value.slice();return filtered.sort((left,right)=>left.kind===right.kind?basename(left.path).localeCompare(basename(right.path),undefined,{numeric:true,sensitivity:"base"}):left.kind==="directory"?-1:1)});
const breadcrumbs=computed(()=>{const result=[{label:rootKind.value.toUpperCase(),path:""}];let path="";for(const segment of currentPath.value.split("/").filter(Boolean)){path=path?`${path}/${segment}`:segment;result.push({label:segment,path})}return result});
const editorBytes=computed(()=>new TextEncoder().encode(editorContent.value).length);
const root=computed(()=>({site_id:siteID.value,kind:rootKind.value}));

onMounted(()=>void bootstrap());watch([siteID,rootKind],()=>{currentPath.value="";cursors.value=[];selected.value=null;if(siteID.value)void load("")});

async function bootstrap():Promise<void>{loading.value=true;error.value="";try{if(api.available("hosting.site.list")){const response=await api.invoke<unknown>("hosting.site.list",{tenantId:sessionStore.state.tenantId,payload:{limit:500}});sites.value=collection(response.result).map((item)=>({id:String(item.id||item.site_id),label:String(item.primary_hostname||item.hostname||item.name||item.id)})).filter((item)=>item.id)}const firstSite=sites.value[0];if(!firstSite)throw new Error("Create or select a site before browsing files.");siteID.value=firstSite.id}catch(cause){error.value=message(cause);loading.value=false}}
async function load(cursor:string):Promise<void>{if(!siteID.value||!api.available("access.files.list")){loading.value=false;return}loading.value=true;error.value="";selected.value=null;try{const response=await api.invoke<unknown>("access.files.list",{tenantId:sessionStore.state.tenantId,resourceId:siteID.value,payload:{root:root.value,directory:currentPath.value,page:{limit:300,cursor:cursor||undefined}}});const page=record(response.result);entries.value=(Array.isArray(page.entries)?page.entries:collection(response.result)) as unknown as FileEntry[];nextCursor.value=String(page.next_cursor||"")}catch(cause){entries.value=[];error.value=message(cause)}finally{loading.value=false}}
function navigate(path:string):void{currentPath.value=path;cursors.value=[];void load("")}
function open(entry:FileEntry):void{selected.value=entry;if(entry.kind==="directory")navigate(entry.path);else void edit(entry)}
async function edit(entry:FileEntry):Promise<void>{if(entry.kind!=="regular"||!api.available("access.files.read_editor"))return;editorOpen.value=true;editorLoading.value=true;editorContent.value="";error.value="";try{const response=await api.invoke<{content:string|number[];entry:FileEntry}>("access.files.read_editor",{tenantId:sessionStore.state.tenantId,resourceId:siteID.value,payload:{source:{root:root.value,path:entry.path},condition:{if_match:entry.etag}}});editorContent.value=decodeBytes(response.result.content);editorOriginalETag.value=response.result.entry?.etag||entry.etag;selected.value=response.result.entry||entry}catch(cause){editorOpen.value=false;error.value=message(cause)}finally{editorLoading.value=false}}
async function saveEditor():Promise<void>{if(!selected.value)return;busy.value=true;try{await mutate("write_file",{path:selected.value.path},{path:selected.value.path},editorContent.value,{if_match:editorOriginalETag.value});editorOpen.value=false;await load("")}catch(cause){error.value=message(cause)}finally{busy.value=false}}
async function createEntry():Promise<void>{const name=create.name.trim();if(!validName(name)){error.value="A name must be one safe path component.";return}const destination=join(currentPath.value,name);busy.value=true;try{await mutate(create.kind==="directory"?"create_directory":"create_file",{path:""},{path:destination},create.content,{if_none_match:true});createOpen.value=false;create.name="";create.content="";await load("")}catch(cause){error.value=message(cause)}finally{busy.value=false}}
async function mutate(kind:string,source:{path:string},destination:{path:string},content="",condition:Record<string,unknown>={}):Promise<void>{await api.invoke("access.files.mutate",{tenantId:sessionStore.state.tenantId,resourceId:siteID.value,payload:{kind,source:{root:root.value,path:source.path},destination:{root:root.value,path:destination.path},metadata:{mode:kind==="create_directory"?493:420,ownership:"site_user"},content:encodeBytes(content),condition}})}
async function upload(files:FileList|null):Promise<void>{if(!files?.length)return;busy.value=true;error.value="";try{for(const file of Array.from(files)){if(file.size>4*1024*1024)throw new Error(`${file.name} is larger than the direct 4 MiB editor-upload limit.`);if(!validName(file.name))throw new Error(`${file.name} is not a safe file name.`);const bytes=new Uint8Array(await file.arrayBuffer());await api.invoke("access.files.mutate",{tenantId:sessionStore.state.tenantId,resourceId:siteID.value,payload:{kind:"create_file",source:{root:root.value,path:""},destination:{root:root.value,path:join(currentPath.value,file.name)},metadata:{mode:420,ownership:"site_user"},content:base64(bytes),condition:{if_none_match:true}}})}await load("")}catch(cause){error.value=message(cause)}finally{busy.value=false;if(uploadInput.value)uploadInput.value.value=""}}
function onUploadChange(event:Event):void{void upload((event.target as HTMLInputElement|null)?.files||null)}
async function trash(entry:FileEntry):Promise<void>{const operation=firstAvailable("access.trash.move","access.file.trash");if(!operation){error.value="Trash operations are not enabled on this node.";return}busy.value=true;try{const response=await api.invoke<TrashedEntry>(operation,{tenantId:sessionStore.state.tenantId,resourceId:siteID.value,payload:{source:{root:root.value,path:entry.path}}});trashed.value.push(response.result);selected.value=null;await load("")}catch(cause){error.value=message(cause)}finally{busy.value=false}}
async function restore(entry:TrashedEntry):Promise<void>{busy.value=true;error.value="";try{await api.invoke("access.trash.restore",{tenantId:sessionStore.state.tenantId,resourceId:entry.site_id,payload:{entry_id:entry.id,destination:entry.original,condition:{if_none_match:true}}});trashed.value=trashed.value.filter((item)=>item.id!==entry.id);await load("")}catch(cause){error.value=message(cause)}finally{busy.value=false}}
function beginRename(entry:FileEntry):void{renameEntry.value=entry;renameName.value=basename(entry.path)}
async function rename():Promise<void>{const entry=renameEntry.value;const name=renameName.value.trim();if(!entry||!validName(name)){error.value="A name must be one safe path component.";return}busy.value=true;error.value="";try{await mutate("move",{path:entry.path},{path:join(currentPath.value,name)},"",{if_none_match:true});renameEntry.value=null;await load("")}catch(cause){error.value=message(cause)}finally{busy.value=false}}
async function download(entry:FileEntry):Promise<void>{const operation=firstAvailable("access.download.issue","access.files.download.issue");if(!operation){error.value="Download leases are not enabled on this node.";return}try{const response=await api.invoke<Record<string,unknown>>(operation,{tenantId:sessionStore.state.tenantId,resourceId:siteID.value,payload:{source:{root:root.value,path:entry.path}}});const url=String(response.result.download_url||response.result.url||"");if(url)window.location.assign(url);else error.value="The node issued a download lease without a browser URL."}catch(cause){error.value=message(cause)}}
function next():void{if(!nextCursor.value)return;cursors.value.push(nextCursor.value);void load(nextCursor.value)}function previous():void{cursors.value.pop();void load(cursors.value[cursors.value.length-1]||"")}
function firstAvailable(...names:string[]):string{return names.find((name)=>api.available(name))||""}function validName(value:string):boolean{return value!==""&&value!=="."&&value!==".."&&!value.includes("/")&&!value.includes("\\")&&!value.includes("\0")&&new TextEncoder().encode(value).length<=255}function join(parent:string,name:string):string{return parent?`${parent}/${name}`:name}function basename(path:string):string{return path.split("/").pop()||path}function collection(value:unknown):Record<string,unknown>[]{if(Array.isArray(value))return value.filter(isRecord);const item=record(value);const raw=Array.isArray(item.items)?item.items:Array.isArray(item.resources)?item.resources:Array.isArray(item.results)?item.results:[];return raw.filter(isRecord)}function record(value:unknown):Record<string,unknown>{return isRecord(value)?value:{}}function isRecord(value:unknown):value is Record<string,unknown>{return Boolean(value)&&typeof value==="object"&&!Array.isArray(value)}function message(cause:unknown):string{return cause instanceof Error?cause.message:"The file operation failed."}function formatBytes(value:number):string{if(!Number.isFinite(value))return "—";const units=["B","KiB","MiB","GiB","TiB"];let amount=Math.max(0,value),index=0;while(amount>=1024&&index<units.length-1){amount/=1024;index++}return `${amount<10&&index?amount.toFixed(1):Math.round(amount)} ${units[index]}`}function formatDate(value:string):string{const date=new Date(value);return Number.isNaN(date.valueOf())?"—":new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(date)}function mode(value:number):string{return `0${(Number(value)||0).toString(8).slice(-3)}`}function encodeBytes(value:string):string{return base64(new TextEncoder().encode(value))}function base64(value:Uint8Array):string{let binary="";for(let offset=0;offset<value.length;offset+=32768)binary+=String.fromCharCode(...value.subarray(offset,offset+32768));return btoa(binary)}function decodeBytes(value:string|number[]):string{if(Array.isArray(value))return new TextDecoder().decode(new Uint8Array(value));const binary=atob(value||"");const bytes=new Uint8Array(binary.length);for(let index=0;index<binary.length;index++)bytes[index]=binary.charCodeAt(index);return new TextDecoder().decode(bytes)}
</script>

<template>
  <main class="files-page">
    <header class="files-head"><div><p>SCOPED SITE FILESYSTEM</p><h2>Files</h2></div><div class="file-actions"><input ref="uploadInput" hidden type="file" multiple @change="onUploadChange"/><button class="button" type="button" :disabled="busy||!siteID" @click="uploadInput?.click()"><UploadSimple :size="15"/>Upload</button><button class="button button-primary" type="button" :disabled="busy||!siteID" @click="createOpen=true"><Plus :size="15"/>New</button></div></header>
    <section class="scope-bar"><label>Site<select v-model="siteID" class="select"><option v-for="site in sites" :key="site.id" :value="site.id">{{site.label}}</option></select></label><label>Root<select v-model="rootKind" class="select"><option value="public">Public</option><option value="private">Private</option><option value="logs">Logs</option><option value="staging">Staging</option><option value="site">Complete site</option></select></label><nav aria-label="Current path"><button v-for="(crumb,index) in breadcrumbs" :key="crumb.path||'root'" type="button" @click="navigate(crumb.path)"><CaretRight v-if="index" :size="12"/>{{crumb.label}}</button></nav><button class="icon-button" type="button" :disabled="loading" aria-label="Refresh" @click="load('')"><ArrowClockwise :size="16"/></button></section>
    <div v-if="error" class="file-error" role="alert">{{error}}</div>
    <div v-for="entry in trashed.filter((item)=>item.site_id===siteID)" :key="entry.id" class="file-actions" role="status"><span>Moved {{basename(entry.original.path)}} to trash.</span><button class="button" type="button" :disabled="busy" @click="restore(entry)">Restore {{basename(entry.original.path)}}</button></div>
    <div v-if="selected" class="file-actions"><button class="button" type="button" :disabled="busy" @click="beginRename(selected)">Rename</button></div>
    <section class="file-workspace">
      <div class="file-table"><header><label><MagnifyingGlass :size="15"/><input v-model="search" type="search" placeholder="Filter this directory"/></label><span>{{visibleEntries.length}} entries</span></header><div class="file-columns"><span>Name</span><span>Size</span><span>Owner</span><span>Mode</span><span>Modified</span></div><div v-if="loading" class="file-loading"><span v-for="index in 9" :key="index" class="skeleton"></span></div><button v-for="entry in visibleEntries" v-else :key="entry.path" type="button" :class="{selected:selected?.path===entry.path}" @click="selected=entry" @dblclick="open(entry)"><span class="entry-name"><Folder v-if="entry.kind==='directory'" :size="18" weight="fill"/><FileCode v-else-if="entry.kind==='regular'" :size="18"/><File v-else :size="18"/><strong>{{basename(entry.path)}}</strong><small v-if="entry.link_target">→ {{entry.link_target}}</small></span><span>{{entry.kind==='directory'?'—':formatBytes(entry.size)}}</span><span>{{entry.owner}}:{{entry.group}}</span><span class="mono">{{mode(entry.mode)}}</span><time>{{formatDate(entry.modified_at)}}</time></button><div v-if="!loading&&!visibleEntries.length" class="file-empty"><FolderOpen :size="31"/><strong>This directory is empty</strong></div><footer v-if="nextCursor||cursors.length"><button class="button button-small" type="button" :disabled="!cursors.length" @click="previous">Previous</button><button class="button button-small" type="button" :disabled="!nextCursor" @click="next">Next</button></footer></div>
      <aside class="inspector"><template v-if="selected"><div class="inspect-symbol"><Folder v-if="selected.kind==='directory'" :size="32" weight="fill"/><FileCode v-else :size="32"/></div><h3>{{basename(selected.path)}}</h3><p>{{selected.path}}</p><dl><div><dt>Type</dt><dd>{{selected.kind}}</dd></div><div><dt>Size</dt><dd>{{formatBytes(selected.size)}}</dd></div><div><dt>Owner</dt><dd>{{selected.owner}}:{{selected.group}}</dd></div><div><dt>Mode</dt><dd class="mono">{{mode(selected.mode)}}</dd></div><div><dt>Modified</dt><dd>{{formatDate(selected.modified_at)}}</dd></div><div><dt>ETag</dt><dd class="mono digest">{{selected.etag}}</dd></div></dl><div class="inspect-actions"><button v-if="selected.kind==='directory'" class="button" type="button" @click="navigate(selected.path)"><FolderOpen :size="15"/>Open</button><button v-if="selected.kind==='regular'&&api.available('access.files.read_editor')" class="button" type="button" @click="edit(selected)"><PencilSimple :size="15"/>Edit</button><button v-if="selected.kind==='regular'" class="button" type="button" @click="download(selected)"><DownloadSimple :size="15"/>Download</button><button class="button button-danger" type="button" :disabled="busy" @click="trash(selected)"><Trash :size="15"/>Trash</button></div></template><div v-else class="inspect-empty"><Copy :size="28"/><strong>Select an entry</strong><span>Details and valid actions appear here.</span></div></aside>
    </section>
    <div v-if="editorOpen" class="modal-layer"><form class="editor-modal" @submit.prevent="saveEditor"><header><div><p>UTF-8 EDITOR / ETAG GUARDED</p><h3>{{selected&&basename(selected.path)}}</h3></div><button type="button" @click="editorOpen=false"><X :size="18"/></button></header><div v-if="editorLoading" class="editor-loading"><span class="skeleton"></span></div><textarea v-else v-model="editorContent" spellcheck="false"></textarea><footer><span class="mono">{{editorBytes}} BYTES</span><button class="button" type="button" @click="editorOpen=false">Cancel</button><button class="button button-primary" type="submit" :disabled="busy||editorLoading">Save atomically</button></footer></form></div>
    <div v-if="createOpen" class="modal-layer"><form class="create-modal" @submit.prevent="createEntry"><header><div><p>CREATE UNDER CURRENT ROOT</p><h3>New entry</h3></div><button type="button" @click="createOpen=false"><X :size="18"/></button></header><div class="create-fields"><label>Type<select v-model="create.kind" class="select"><option value="file">File</option><option value="directory">Directory</option></select></label><label>Name<input v-model="create.name" class="input" required autocomplete="off"/></label><label v-if="create.kind==='file'">Initial content<textarea v-model="create.content" class="textarea" spellcheck="false"></textarea></label></div><footer><button class="button" type="button" @click="createOpen=false">Cancel</button><button class="button button-primary" type="submit" :disabled="busy">Create</button></footer></form></div>
    <div v-if="renameEntry" class="modal-layer"><form class="create-modal" @submit.prevent="rename"><header><h3>Rename {{basename(renameEntry.path)}}</h3><button type="button" @click="renameEntry=null"><X :size="18"/></button></header><div class="create-fields"><label>New name<input v-model="renameName" class="input" required autocomplete="off"/></label></div><footer><button class="button" type="button" @click="renameEntry=null">Cancel</button><button class="button button-primary" type="submit" :disabled="busy">Rename entry</button></footer></form></div>
  </main>
</template>

<style scoped>
