background:var(--bg-raised)}.file-table>header input{width:100%;border:0;outline:0;background:transparent;color:var(--text)}.file-table>header span{color:var(--subtle);font-size:10px}.file-columns,.file-table>button{display:grid;grid-template-columns:minmax(260px,1fr) 85px 120px 70px 145px;align-items:center;gap:10px;padding:0 12px}.file-columns{height:31px;position:sticky;z-index:2;top:48px;border-bottom:1px solid var(--border);background:var(--bg-raised);color:var(--subtle);font:9px/1 "Panel Mono",monospace;text-transform:uppercase}.file-table>button{width:100%;min-height:47px;border:0;border-bottom:1px solid var(--border);background:transparent;color:var(--muted);font-size:11px;text-align:left;cursor:pointer}.file-table>button:hover,.file-table>button.selected{background:var(--surface-2);color:var(--text)}.file-table>button.selected{box-shadow:inset 2px 0 var(--accent)}.entry-name{min-width:0;display:flex;align-items:center;gap:9px;color:var(--accent)}.entry-name strong{color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.entry-name small{color:var(--subtle);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-loading{padding:12px;display:grid;gap:9px}.file-loading span{height:35px}.file-empty{min-height:320px;display:grid;place-content:center;justify-items:center;gap:8px;color:var(--subtle)}.file-empty strong{color:var(--text)}.file-table>footer{padding:12px;display:flex;justify-content:flex-end;gap:8px}.inspector{padding:23px;overflow:auto}.inspect-symbol{width:58px;height:58px;border:1px solid var(--border);border-radius:10px;display:grid;place-items:center;color:var(--accent);background:var(--accent-soft)}.inspector h3{margin:17px 0 3px;overflow-wrap:anywhere}.inspector>p{margin:0;color:var(--subtle);font-size:10px;overflow-wrap:anywhere}.inspector dl{margin:22px 0;display:grid}.inspector dl div{padding:9px 0;border-bottom:1px solid var(--border);display:grid;grid-template-columns:75px 1fr;gap:7px}.inspector dt{color:var(--s